export function sanitizeSettings(raw={},previous=DEFAULTS){const s={...previous};for(const [k,min,max] of [['scoreLimit',5,200],['timeLimit',1,60],['respawn',1,10],['maxHP',50,500],['armor',0,100],['spawnProtection',0,3],['moveSpeed',.5,1.5]])if(Number.isFinite(+raw[k]))s[k]=Math.max(min,Math.min(max,+raw[k]));for(const k of ['friendlyFire','headshotsOnly'])if(typeof raw[k]==='boolean')s[k]=raw[k];if(MODES[raw.mode])s.mode=raw.mode;if(MAPS[raw.map])s.map=raw.map;if(Object.hasOwn(BOT_LEVELS,raw.botDifficulty))s.botDifficulty=raw.botDifficulty;return s;}
